input.command:
cd /home/vscode/rebaseline
ok=0; nowr=0; div=0; other=0
for f in basis/artifacts/*.md; do
  out=$(python3 basis/tools/compile_typedef.py "$f" --check 2>&1)
  if echo "$out" | grep -qi "diverged"; then div=$((div+1)); echo "DIVERGED $(basename $f)";
  elif echo "$out" | grep -qi "Writing rules"; then nowr=$((nowr+1));
  elif echo "$out" | grep -qi "current\|ok"; then ok=$((ok+1)); echo "OK $(basename $f)";
  else other=$((other+1)); echo "OTHER $(basename $f): $(echo "$out"|head -1)"; fi
done
echo "ok=$ok no-writing-rules=$nowr diverged=$div other=$other"
